using UnityEngine;

namespace AlienInvaders.Views
{
    /// <summary>
    /// Temporary sound effects generated by code (tones, sweeps and filtered noise), so the game already has spatial
    /// audio before the real sounds arrive with the final art, and no audio files are needed in the repository yet.
    /// Each clip is built once, the first time it is asked for. Looping clips hold a whole number of cycles of every
    /// tone, so they repeat without clicks.
    /// </summary>
    public static class PlaceholderSounds
    {
        private const int SampleRate = 22050;

        private static readonly System.Random NoiseSource = new System.Random(7);
        private static AudioClip _charge;
        private static AudioClip _enemyShot;
        private static AudioClip _explosion;
        private static AudioClip _portalHum;
        private static AudioClip _engine;
        private static AudioClip _playerShot;
        private static AudioClip _overheat;
        private static AudioClip _rumble;
        private static AudioClip _alarm;
        private static AudioClip _beep;
        private static AudioClip _go;
        private static AudioClip _powerUpAppear;
        private static AudioClip _powerUpHit;
        private static AudioClip _powerUp;
        private static AudioClip _superHum;

        /// <summary>Loop: buzzing tone of a ship charging its shot (the ShipView raises its pitch).</summary>
        public static AudioClip Charge => _charge != null ? _charge : (_charge = BuildCharge());

        /// <summary>Heavy downward zap of an enemy shot.</summary>
        public static AudioClip EnemyShot => _enemyShot != null ? _enemyShot : (_enemyShot = BuildEnemyShot());

        /// <summary>Noise burst with a low thump.</summary>
        public static AudioClip Explosion => _explosion != null ? _explosion : (_explosion = BuildExplosion());

        /// <summary>Loop: deep drone of an open portal.</summary>
        public static AudioClip PortalHum => _portalHum != null ? _portalHum : (_portalHum = BuildPortalHum());

        /// <summary>Loop: quiet engine of a flying ship (helps to hear where ships are).</summary>
        public static AudioClip Engine => _engine != null ? _engine : (_engine = BuildEngine());

        /// <summary>Short, bright zap of the player's blaster.</summary>
        public static AudioClip PlayerShot => _playerShot != null ? _playerShot : (_playerShot = BuildPlayerShot());

        /// <summary>Steam hiss when the blaster overheats.</summary>
        public static AudioClip Overheat => _overheat != null ? _overheat : (_overheat = BuildOverheat());

        /// <summary>Deep structural rumble when the tower drops.</summary>
        public static AudioClip Rumble => _rumble != null ? _rumble : (_rumble = BuildRumble());

        /// <summary>Loop: two-tone alarm of the critical state.</summary>
        public static AudioClip Alarm => _alarm != null ? _alarm : (_alarm = BuildAlarm());

        /// <summary>Short clean tone for each number of the countdown.</summary>
        public static AudioClip Beep => _beep != null ? _beep : (_beep = BuildBeep());

        /// <summary>Rising two-note signal when the ships come out of the portals.</summary>
        public static AudioClip Go => _go != null ? _go : (_go = BuildGo());

        /// <summary>Sparkling rising chime when power up cubes come out of a blast.</summary>
        public static AudioClip PowerUpAppear =>
            _powerUpAppear != null ? _powerUpAppear : (_powerUpAppear = BuildPowerUpAppear());

        /// <summary>Short bright ping of a bolt hitting the cubes (the pickup raises its pitch with every hit).</summary>
        public static AudioClip PowerUpHit => _powerUpHit != null ? _powerUpHit : (_powerUpHit = BuildPowerUpHit());

        /// <summary>Rising charge up when the cubes are collected and the super weapon starts.</summary>
        public static AudioClip PowerUp => _powerUp != null ? _powerUp : (_powerUp = BuildPowerUp());

        /// <summary>Loop: crackling electric hum of the super weapon.</summary>
        public static AudioClip SuperHum => _superHum != null ? _superHum : (_superHum = BuildSuperHum());

        private static AudioClip BuildCharge()
        {
            // 0.4 s: 220 Hz = 88 cycles and 222.5 Hz = 89 cycles (the beating between them sounds electric).
            float[] data = NewBuffer(0.4f);
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                float tremolo = 0.75f + 0.25f * Mathf.Sin(2f * Mathf.PI * 12.5f * t);
                data[i] = 0.45f * tremolo * (Saw(220f * t) + Saw(222.5f * t)) * 0.5f;
            }
            return ToClip("Charge", data);
        }

        private static AudioClip BuildEnemyShot()
        {
            float[] data = NewBuffer(0.35f);
            float phase = 0f;
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                // Exponential sweep from 1400 Hz down to 150 Hz.
                float frequency = 1400f * Mathf.Pow(150f / 1400f, t / 0.35f);
                phase += frequency / SampleRate;
                float tone = Tanh(3f * Mathf.Sin(2f * Mathf.PI * phase));
                data[i] = (0.8f * tone + 0.2f * Noise()) * Mathf.Exp(-t * 9f);
            }
            return ToClip("EnemyShot", data);
        }

        private static AudioClip BuildExplosion()
        {
            float[] data = NewBuffer(1.2f);
            float low = 0f;
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                // The noise gets darker as it fades, like a fireball turning into smoke.
                float cutoff = Mathf.Lerp(3000f, 300f, t / 1.2f);
                low = LowPass(low, Noise(), cutoff);
                float thump = Mathf.Sin(2f * Mathf.PI * 50f * t) * Mathf.Exp(-t * 8f);
                float attack = Mathf.Clamp01(t / 0.005f);
                data[i] = attack * (1.6f * low * Mathf.Exp(-t * 3.5f) + 0.8f * thump);
            }
            return ToClip("Explosion", data);
        }

        private static AudioClip BuildPortalHum()
        {
            // 2 s: 55 Hz = 110 cycles, 82.5 Hz = 165 cycles, and one slow swell per loop.
            float[] data = NewBuffer(2f);
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                float swell = 0.7f + 0.3f * Mathf.Sin(2f * Mathf.PI * 0.5f * t);
                data[i] = 0.6f * swell * (0.6f * Mathf.Sin(2f * Mathf.PI * 55f * t) +
                                           0.4f * Tanh(2f * Mathf.Sin(2f * Mathf.PI * 82.5f * t)));
            }
            return ToClip("PortalHum", data);
        }

        private static AudioClip BuildEngine()
        {
            // 0.5 s: 110 Hz = 55 cycles, 164 Hz = 82 cycles, flutter at 6 Hz = 3 cycles.
            float[] data = NewBuffer(0.5f);
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                float flutter = 0.8f + 0.2f * Mathf.Sin(2f * Mathf.PI * 6f * t);
                data[i] = 0.3f * flutter * (0.6f * Saw(110f * t) + 0.4f * Mathf.Sin(2f * Mathf.PI * 164f * t));
            }
            return ToClip("Engine", data);
        }

        private static AudioClip BuildPlayerShot()
        {
            float[] data = NewBuffer(0.12f);
            float phase = 0f;
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                float frequency = 2400f * Mathf.Pow(700f / 2400f, t / 0.12f);
                phase += frequency / SampleRate;
                data[i] = 0.6f * Tanh(2f * Mathf.Sin(2f * Mathf.PI * phase)) * Mathf.Exp(-t * 30f);
            }
            return ToClip("PlayerShot", data);
        }

        private static AudioClip BuildOverheat()
        {
            float[] data = NewBuffer(0.9f);
            float previous = 0f;
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                // Difference of consecutive noise samples = bright hiss (a crude high-pass filter).
                float noise = Noise();
                float hiss = noise - previous;
                previous = noise;
                data[i] = 0.35f * hiss * Mathf.Clamp01(t / 0.02f) * Mathf.Exp(-t * 3f);
            }
            return ToClip("Overheat", data);
        }

        private static AudioClip BuildRumble()
        {
            float[] data = NewBuffer(1.5f);
            float low = 0f;
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                low = LowPass(low, Noise(), 180f);
                float body = 3f * low + 0.5f * Mathf.Sin(2f * Mathf.PI * 35f * t);
                data[i] = body * Mathf.Clamp01(t / 0.02f) * Mathf.Exp(-t * 2.5f);
            }
            return ToClip("Rumble", data);
        }

        private static AudioClip BuildAlarm()
        {
            // 1 s: 660 Hz then 880 Hz, half a second each (whole cycles, so the switch does not click).
            float[] data = NewBuffer(1f);
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                float frequency = t < 0.5f ? 660f : 880f;
                data[i] = 0.4f * Tanh(2f * Mathf.Sin(2f * Mathf.PI * frequency * t));
            }
            return ToClip("Alarm", data);
        }

        private static AudioClip BuildBeep()
        {
            float[] data = NewBuffer(0.15f);
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                data[i] = 0.5f * Mathf.Sin(2f * Mathf.PI * 880f * t) * Mathf.Clamp01(t / 0.005f) * Mathf.Exp(-t * 12f);
            }
            return ToClip("Beep", data);
        }

        private static AudioClip BuildGo()
        {
            // Two quick notes a fifth apart (A5 then E6), the second one held a little longer.
            float[] data = NewBuffer(0.45f);
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                float frequency = t < 0.12f ? 880f : 1318.5f;
                float local = t < 0.12f ? t : t - 0.12f;
                data[i] = 0.45f * Tanh(1.5f * Mathf.Sin(2f * Mathf.PI * frequency * t)) *
                          Mathf.Clamp01(local / 0.005f) * Mathf.Exp(-local * 6f);
            }
            return ToClip("Go", data);
        }

        private static AudioClip BuildPowerUpAppear()
        {
            // Three quick notes going up (C6, E6, G6), each one ringing on under the next, like a sparkle.
            float[] notes = { 1046.5f, 1318.5f, 1568f };
            float[] data = NewBuffer(0.6f);
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                float sum = 0f;
                for (int n = 0; n < notes.Length; n++)
                {
                    float local = t - n * 0.07f;
                    if (local > 0f)
                    {
                        sum += Mathf.Sin(2f * Mathf.PI * notes[n] * local) * Mathf.Clamp01(local / 0.004f) *
                               Mathf.Exp(-local * 7f);
                    }
                }
                data[i] = 0.3f * sum;
            }
            return ToClip("PowerUpAppear", data);
        }

        private static AudioClip BuildPowerUpHit()
        {
            // A glassy ping: a tone and its octave, with a tiny click of noise at the start.
            float[] data = NewBuffer(0.14f);
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                float tone = 0.7f * Mathf.Sin(2f * Mathf.PI * 1175f * t) + 0.3f * Mathf.Sin(2f * Mathf.PI * 2350f * t);
                float click = Noise() * Mathf.Exp(-t * 400f);
                data[i] = (0.5f * tone * Mathf.Exp(-t * 28f) + 0.2f * click) * Mathf.Clamp01(t / 0.002f);
            }
            return ToClip("PowerUpHit", data);
        }

        private static AudioClip BuildPowerUp()
        {
            // 0.8 s: a buzzing sweep from 220 Hz up to 1760 Hz, then a bright chord rings out.
            float[] data = NewBuffer(0.8f);
            float phase = 0f;
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                float sweep = 0f;
                if (t < 0.45f)
                {
                    float frequency = 220f * Mathf.Pow(1760f / 220f, t / 0.45f);
                    phase += frequency / SampleRate;
                    sweep = 0.4f * Tanh(2f * Saw(phase)) * Mathf.Clamp01(t / 0.01f) * Mathf.Clamp01((0.45f - t) / 0.02f);
                }
                float ring = 0f;
                if (t >= 0.4f)
                {
                    float local = t - 0.4f;
                    ring = (Mathf.Sin(2f * Mathf.PI * 1760f * local) + 0.6f * Mathf.Sin(2f * Mathf.PI * 2637f * local)) *
                           0.25f * Mathf.Clamp01(local / 0.005f) * Mathf.Exp(-local * 6f);
                }
                data[i] = sweep + ring;
            }
            return ToClip("PowerUp", data);
        }

        private static AudioClip BuildSuperHum()
        {
            // 1 s: 120 Hz = 120 cycles and 181 Hz = 181 cycles, a throb at 8 Hz = 8 cycles, and random crackles.
            float[] data = NewBuffer(1f);
            float crackle = 0f;
            for (int i = 0; i < data.Length; i++)
            {
                float t = (float)i / SampleRate;
                float throb = 0.75f + 0.25f * Mathf.Sin(2f * Mathf.PI * 8f * t);
                float buzz = 0.6f * Saw(120f * t) + 0.4f * Tanh(2f * Mathf.Sin(2f * Mathf.PI * 181f * t));
                // About 25 sparks per second, each a short burst of hiss.
                if (NoiseSource.NextDouble() < 25.0 / SampleRate)
                {
                    crackle = 1f;
                }
                crackle *= 0.995f;
                data[i] = 0.3f * throb * buzz + 0.35f * crackle * Noise();
            }
            return ToClip("SuperHum", data);
        }

        private static float[] NewBuffer(float seconds)
        {
            return new float[Mathf.RoundToInt(seconds * SampleRate)];
        }

        private static AudioClip ToClip(string name, float[] data)
        {
            for (int i = 0; i < data.Length; i++)
            {
                data[i] = Mathf.Clamp(data[i], -1f, 1f);
            }
            AudioClip clip = AudioClip.Create(name, data.Length, 1, SampleRate, false);
            clip.SetData(data, 0);
            return clip;
        }

        // White noise between -1 and 1.
        private static float Noise()
        {
            return (float)(NoiseSource.NextDouble() * 2.0 - 1.0);
        }

        // One-pole low-pass filter: keeps the rumble, removes the hiss above the cutoff frequency.
        private static float LowPass(float previous, float input, float cutoff)
        {
            float a = 1f - Mathf.Exp(-2f * Mathf.PI * cutoff / SampleRate);
            return previous + a * (input - previous);
        }

        // Sawtooth between -1 and 1 for a phase measured in cycles.
        private static float Saw(float cycles)
        {
            return 2f * (cycles - Mathf.Floor(cycles + 0.5f));
        }

        // Soft clipping: rounds a sine into a buzzier, square-like wave without harsh edges.
        private static float Tanh(float x)
        {
            float e = Mathf.Exp(2f * x);
            return (e - 1f) / (e + 1f);
        }
    }
}
